            mdev = norm(cs.origin - nomadEHingeFrame().origin) / millimeter;
        }
        // structural / service parts a fastener head must not overlap (keep-outs and envelopes excluded)
        var hard = [];
        for (var n in ["BASE_SHELL", "KEYBOARD_TRAY", "TRACKPAD_TRAY", "COMPUTE_SLED", "SERVICE_PANEL_MAIN", "BATTERY_DOOR",
                    "PORT_PANEL_MAIN", "PORT_PANEL_AUX", "PANEL_STANDOFF_L", "PANEL_STANDOFF_R"])
            hard = append(hard, parts[n]);
        var over = [];
        for (var h in svc.fasteners)
        {
            if (e1State(context, h, qUnion(hard)) == "O")
                over = append(over, getProperty(context, { "entity" : h, "propertyType" : PropertyType.NAME }));
        }
        var msg = "E1 n" ~ solids ~ " mc" ~ size(mcs) ~ " L" ~ lumps ~ " S" ~ stBad ~ "/" ~ size(BV_PAIRS) ~ " c" ~ nCmp ~
            " dv" ~ e1R(dev) ~ " m" ~ e1R(mdev) ~ " f" ~ size(svc.fasteners) ~ " fo" ~ size(over) ~ ":";
        for (var s in over)
            msg = msg ~ " " ~ replace(s, "FASTENER_M3 \\[representative\\] ", "");
        msg = msg ~ " F:";
        for (var i = 0; i < size(fails); i += 1)
            msg = msg ~ " " ~ fails[i];
        throw regenError(msg);
    }, {});
